import java.util.*;

class MedianFinder {
    private PriorityQueue<Integer> small = new PriorityQueue<>((a, b) -> Integer.compare(b, a)); // max-heap
    private PriorityQueue<Integer> large = new PriorityQueue<>();                                 // min-heap

    public MedianFinder() {
    }

    public void addNum(int num) {
        small.offer(num);
        large.offer(small.poll());              // pass the max of the lower half up
        if (large.size() > small.size()) {
            small.offer(large.poll());          // rebalance so small >= large in size
        }
    }

    public double findMedian() {
        if (small.size() > large.size()) return small.peek();
        return (small.peek() + large.peek()) / 2.0;
    }
}
